Chapter: Nine days

The paragraph: In June the share price fell from 104.5 euros to 1.28 euros. Nobody could stop it.

This graphic covers: The share price fell from 104.5 euros to 1.28 euros.
Length: 7.0 s

Words spoken in it, from its start:
0.3 s  "We
0.8 s  never
1.3 s  saw
1.8 s  the
2.3 s  money,"
2.8 s  the
3.3 s  chairman
3.8 s  told
4.3 s  the
4.8 s  court.

Intent: The chairman told the court they never saw the money.
Rests on claims: 4

A passing design of this technique (quote-card: a large opening mark that settles into the margin as the quotation builds, the attribution drawn off it by a rule), in this sandbox and on the tokens, to pattern on. Its words and figures are its own; yours come from this slot and its claims:
````jsx
// Concept: the quotation mark opens the floor. A large opening mark is the first thing on
// screen; as the speaker's first word is said it settles into place, hanging in the margin
// before the quote, and the words follow it as they are spoken. The attribution is drawn off
// the quote by a rule once the quote is closed.
// Storyboard, on the narration's clock:
//   0.0 s  the hook: the opening mark lands large in the accent where the quote will begin
//   0.3 s  "We": the mark settles to its hanging size and the first word rises in beside it
//   0.8 s to 2.3 s  "never saw the money,": each word rises in as it is said, the closing
//          mark landing with the last of them
//   2.8 s  "the chairman told the court.": a short rule draws under the quote's start and the
//          attribution builds beside it, word by word
//   to the end: the quote holds while the camera keeps a slow push
// The quote is the words up to the one that closes the quotation; the rest is the attribution.

// Helpers, called directly: 0 to 1 over lengthMs from atMs, held at 1, one per curve,
// since each interpolate names its curve in the call.
function range(fps, atMs, lengthMs) {
  return [motion.frames(atMs, fps), motion.frames(atMs + lengthMs, fps)]
}
function arrive(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.enter, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}
function travel(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.move, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}

// Motion blur that follows speed: a move of more than a few pixels a frame softens, and
// only while it is moving. moved is how far the element travelled since the last frame.
function blurFor(moved, unit) {
  const px = Math.min(8, Math.abs(moved) / (6 * unit)) * unit
  return px > 0.4 * unit ? 'blur(' + px.toFixed(2) + 'px)' : 'none'
}

// A helper, called directly: one spoken word rising in as it is said.
function wordSpan(text, atMs, spec) {
  const enter = arrive(spec.frame, spec.fps, atMs, motion.ms.enter)
  return (
    <span
      key={atMs}
      style={{
        display: 'inline-block', marginRight: '0.24em', opacity: enter,
        transform: 'translateY(' + (1 - enter) * motion.px.rise * spec.unit + 'px)',
      }}
    >
      {text}
    </span>
  )
}

// The quote's words with their marks taken off: the opening mark is drawn as its own object,
// the closing one set in the accent.
function quoteParts(words) {
  const close = words.findIndex((word) => /["”][.,!?]?$|[.,!?]["”]$/.test(word.text))
  const end = close >= 0 ? close : words.length - 1
  const quote = words.slice(0, end + 1).map((word, index) => ({
    atMs: word.atMs,
    text: (index === 0 ? word.text.replace(/^["“]/, '') : word.text).replace(/["”]/g, '').replace(/,$/, ''),
  }))
  return { quote, closeAt: words[end].atMs, attribution: words.slice(end + 1) }
}

function Graphic(props) {
  const frame = Remotion.useCurrentFrame()
  const { width, height, fps } = Remotion.useVideoConfig()
  const { colors, fonts } = props.brand
  const inset = props.safeArea
  const portrait = height > width
  const unit = Math.min(width, height) / 1080

  const parts = React.useMemo(() => quoteParts(props.words), [props.words])
  const firstAt = parts.quote.length > 0 ? parts.quote[0].atMs : 0
  const attributionAt = parts.attribution.length > 0 ? parts.attribution[0].atMs : props.durationMs
  const room = width - inset.left - inset.right
  const quoteText = parts.quote.map((word) => word.text).join(' ')
  const size = Math.min((portrait ? 104 : 116) * unit, Math.sqrt((room * 0.8 * (portrait ? 900 : 520) * unit) / Math.max(1, quoteText.length * 0.55)))

  // The mark: lands large on the first frames, then settles to its hanging size as the quote begins.
  const markIn = arrive(frame, fps, 0, motion.ms.enter)
  const settle = travel(frame, fps, firstAt, motion.ms.move)
  const settleBefore = travel(frame - 1, fps, firstAt, motion.ms.move)
  const markScale = 2.6 - 1.6 * settle
  const closeIn = arrive(frame, fps, parts.closeAt, motion.ms.enter)
  const rule = arrive(frame, fps, attributionAt, motion.ms.draw)
  const push = travel(frame, fps, 0, props.durationMs)
  const spec = { frame, fps, unit }

  return (
    <Remotion.AbsoluteFill
      style={{
        paddingTop: inset.top, paddingRight: inset.right,
        paddingBottom: inset.bottom, paddingLeft: inset.left,
        justifyContent: 'center', alignItems: 'flex-start',
        transform: 'scale(' + (1 + 0.03 * push) + ')', transformOrigin: inset.left + 'px 50%',
      }}
    >
      <div style={{ position: 'relative', paddingLeft: 0.62 * size, maxWidth: portrait ? room : room * 0.86 }}>
        <div
          style={{
            position: 'absolute', left: 0, top: -0.12 * size, fontFamily: fonts.heading, fontSize: size * 1.5,
            // Grown from its foot, so at its large size it stands above the line, clear of the first word.
            lineHeight: 1, color: colors.accent, opacity: markIn, transformOrigin: 'left 60%',
            transform: 'scale(' + markScale + ')', filter: blurFor((settle - settleBefore) * 1.6 * size, unit),
          }}
        >
          {'“'}
        </div>
        <div style={{ fontFamily: fonts.heading, fontSize: size, lineHeight: 1.15, color: colors.textPrimary }}>
          {parts.quote.map((word) => wordSpan(word.text, word.atMs, spec))}
          <span style={{ display: 'inline-block', color: colors.accent, opacity: closeIn, marginLeft: '-0.2em' }}>{'”'}</span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 20 * unit, marginTop: 0.42 * size }}>
          <div style={{ width: 72 * unit * rule, height: 4 * unit, backgroundColor: colors.accent }} />
          <div style={{ fontFamily: fonts.title, fontSize: 48 * unit, color: colors.textSecondary }}>
            {parts.attribution.map((word) => wordSpan(word.text, word.atMs, spec))}
          </div>
        </div>
      </div>
    </Remotion.AbsoluteFill>
  )
}

````
